<?php require dirname(__DIR__).'/inc/page_helpers.php';$id=(int)($_GET['id']??0);$q=$db->prepare('SELECT t.*,u.username FROM forum_topics t JOIN users u ON u.id=t.user_id WHERE t.id=?');$q->execute([$id]);$topic=$q->fetch();$replies=[];if($topic){$q=$db->prepare('SELECT r.*,u.username FROM forum_replies r JOIN users u ON u.id=r.user_id WHERE r.topic_id=? ORDER BY r.id');$q->execute([$id]);$replies=$q->fetchAll();}if($topic&&page_post()){login_required();check_csrf();$body=trim((string)($_POST['body']??''));if($body!==''){$db->prepare('INSERT INTO forum_replies(topic_id,user_id,body) VALUES(?,?,?)')->execute([$id,$currentUser['id'],$body]);notice('Reply posted.');go('/Forum/ShowPost.php?id='.$id);}}page_start($topic?$topic['title']:'Topic not found');?><section class="Panel"><?php if(!$topic):?><h1>Topic not found</h1><?php else:?><h1><?=e($topic['title'])?></h1><?php foreach($replies as $r):?><article class="tile"><b><?=e($r['username'])?></b><small><?=e($r['created_at'])?></small><p><?=nl2br(e($r['body']))?></p><?php if($currentUser&&(int)$currentUser['id']!==(int)$r['user_id']):?><form method="post" action="/Report.php"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="type" value="forum_reply"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><label>Report reason<input name="reason" maxlength="1000" required></label><button>Report reply</button></form><?php endif;?></article><?php endforeach;?><?php if($currentUser):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Reply<textarea name="body" required></textarea></label><button class="Button">Reply</button></form><?php else:?><a href="/Login.php">Login to reply</a><?php endif;?><form method="post" action="/Report.php"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="type" value="forum_topic"><input type="hidden" name="id" value="<?=(int)$topic['id']?>"><label>Report reason<input name="reason" maxlength="1000" required></label><button>Report topic</button></form><?php endif;?></section><?php page_end();?>